import os
from dotenv import load_dotenv
from flask import Flask, session, redirect, url_for, request, render_template_string
import theme_resolver
import theme_palettes

load_dotenv()

app = Flask(__name__)
app.secret_key = os.getenv("FLASK_SECRET_KEY", "supersecretkey")  # Ensure to set a secure secret key in production


def get_demo_interface() -> str:
    """Generate the HTML for the interactive demo interface with database selection."""

    api_key = os.getenv("APP_API_KEY", "")

    if not api_key:
        return """
        <!DOCTYPE html>
        <html>
        <body style="font-family: Arial, sans-serif; text-align: center; margin-top: 100px;">
            <h1 style="color: red;">Configuration Error</h1>
            <p>APP_API_KEY is not configured in environment variables.</p>
            <p>Please set APP_API_KEY in your .env file and restart the server.</p>
        </body>
        </html>
        """

    # Determine active theme and palette
    active_theme = theme_resolver.resolve_theme(session)
    palette = theme_palettes.get_palette(active_theme)

